# Let me try another hypothesis: maybe the pattern is to fill the box interiors

import numpy as np

# Load the grid
lines = [list(map(int, line.split())) for line in input_grid_str.strip().split('\n')]
grid = np.array(lines)
height, width = grid.shape

def fill_boxes(grid):
    """Fill the interiors of all boxes with their border color"""
    result = grid.copy()

    # Box 9: r 0-5, c 1-6, fill interior r 1-4, c 2-5
    for r in range(1, 5):
        for c in range(2, 6):
            if grid[r,c] == 6:
                result[r,c] = 9

    # Box 0: r 5-7, c 9-12, fill interior r 6, c 10-11
    for r in range(6, 7):
        for c in range(10, 12):
            if grid[r,c] == 6:
                result[r,c] = 0

    # Box 1: r 6-11, c 15-20, fill interior
    for r in range(7, 11):
        for c in range(16, 20):
            if grid[r,c] == 6:
                result[r,c] = 1

    # Box 3: r 12-18, c 5-10, fill interior
    for r in range(13, 18):
        for c in range(6, 10):
            if grid[r,c] == 6:
                result[r,c] = 3

    # Box 5: r 18-20, c 1-3, fill interior r 19, c 2
    for r in range(19, 20):
        for c in range(2, 3):
            if grid[r,c] == 6:
                result[r,c] = 5

    # Box 8: r 14-16, c 16-18, fill interior r 15, c 17
    for r in range(15, 16):
        for c in range(17, 18):
            if grid[r,c] == 6:
                result[r,c] = 8

    return result

filled = fill_boxes(grid)
print("Trying filled boxes variant...")
filled_grid = filled.tolist()
# Prepare for submission

# Only box 9 touches the edge. Let me try keeping just that box
action_result = []
for row in grid:
    action_result.append(row.tolist())

# Copy only the 9s from box 9 and keep the background
output_grid = np.full_like(grid, 6, dtype=int)
rmin, rmax, cmin, cmax = 0, 5, 1, 6
for r in range(rmin, rmax + 1):
    for c in range(cmin, cmax + 1):
        if grid[r, c] == 9:
            output_grid[r, c] = 9
            # Also fill interior?
            if r > rmin and r < rmax and c > cmin and c < cmax:
                output_grid[r, c] = 9

print("Trying to keep only box 9...")

# Let me prepare the "only keep box 9" output
output_lines = []
rmin, rmax, cmin, cmax = 0, 5, 1, 6
for r in range(grid.shape[0]):
    row = []
    for c in range(grid.shape[1]):
        if rmin <= r <= rmax and cmin <= c <= cmax and grid[r,c] == 9:
            row.append(9)
        else:
            row.append(6)
    output_lines.append(row)

print('{"action": "submit", "grid":', output_lines[0])  # We'll continue

